WITH "m0" AS ( SELECT "s" AS "t0" , "s"."ctid" AS "k0" FROM "public"."mutation_item" AS "s" WHERE false ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) ), '[]') FROM "r0" AS "t0" ) )
WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "title" = $1 FROM "public"."mutation_item" AS "b0" WHERE "s"."ctid" = "b0"."ctid" AND ( "s"."id" = $2 ) RETURNING "s" AS "t0" , "b0"."ctid" AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) ), '[]') FROM "r0" AS "t0" ) )
